INSERT INTO payment_order(id,payment_no,request_idempotency_key,payment_scene,related_extension_request_id,buyer_user_id,pay_channel,channel_order_mode,
    channel_app_id,channel_mch_id,channel_notify_url,channel_combine_out_trade_no,payer_openid,payment_status,payable_amount_fen,paid_amount_fen,refunded_amount_fen,expire_at,next_attempt_at,created_at,updated_at)
    SELECT #{payment},#{payment},#{key},'extension_rent',e.id,e.buyer_user_id,'wechat_pay','combine_jsapi',p.channel_app_id,p.channel_mch_id,p.channel_notify_url,
    #{payment},p.payer_openid,'pending',e.extension_rent_amount_fen,0,0,#{expiry},#{at},#{at},#{at}
    FROM order_extension_request e JOIN rental_order o ON o.id=e.rental_order_id JOIN payment_order p ON p.checkout_batch_id=o.checkout_batch_id WHERE e.id=#{id}

mapper.update:
UPDATE order_extension_request SET extension_status=#{status},reject_reason=#{reason},refund_order_id=#{refund},
    effective_at=IF(#{status}='approved',#{at},effective_at),factory_handled_at=IF(#{status} IN ('approved','rejected_refunding'),#{at},factory_handled_at),
    updated_at=#{at},version=version+1 WHERE id=#{id}

UPDATE inventory_reservation r JOIN inventory_reservation h ON h.idempotency_key=CONCAT('extend:',#{ext.id},':',r.id)
    SET r.rental_end_date=#{ext.requestedDueDate},r.occupy_end_date=h.occupy_end_date,r.version=r.version+1,r.updated_at=#{at}
    WHERE h.source_id=#{ext.id} AND h.source_type='extension_request' AND h.reservation_status='paid_locked' AND r.reservation_status='renting'
